import { buildApiUrl } from "./environment";

export function url(path: string) {
  return buildApiUrl(path);
}

/** An unsuccessful HTTP response, preserving its status for callers that need it. */
export class HttpError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = "HttpError";
  }
}

/** Builds request headers, adding a `Bearer` auth header when a token is present. */
function buildHeaders(
  clerkToken?: string | null,
  contentTypeJson = false,
  extraHeaders?: Record<string, string>,
): Record<string, string> {
  const headers: Record<string, string> = extraHeaders ? { ...extraHeaders } : {};
  if (contentTypeJson) {
    headers["Content-Type"] = "application/json";
  }
  if (clerkToken) {
    headers["Authorization"] = `Bearer ${clerkToken}`;
  }
  return headers;
}

/**
 * Core fetch scaffold shared by every helper below. Issues the request with the
 * standard `credentials: "include"` and `buildHeaders(...)`, JSON-encoding a
 * body when `withBody` is set (which also selects the JSON content-type header).
 * Returns the raw `Response`; callers own any ok-check and body parsing.
 */
function sendRequest(
  method: string,
  path: string,
  {
    clerkToken,
    jsonPayload,
    withBody = false,
    signal,
    extraHeaders,
  }: {
    clerkToken?: string | null;
    jsonPayload?: unknown;
    withBody?: boolean;
    signal?: AbortSignal;
    extraHeaders?: Record<string, string>;
  } = {},
): Promise<Response> {
  const init: RequestInit = {
    method,
    headers: buildHeaders(clerkToken, withBody, extraHeaders),
    credentials: "include",
  };
  if (withBody) {
    init.body = JSON.stringify(jsonPayload);
  }
  if (signal !== undefined) {
    init.signal = signal;
  }
  return fetch(url(path), init);
}

/**
 * Sends a JSON body via `method` and returns the parsed JSON response as `T`,
 * throwing on a non-ok response (using the response text when present). A body
 * is only parsed when the response is JSON, so endpoints that answer with an
 * empty body (`Promise<void>` callers) are handled too. Shared by `postJson`
 * and `patchJson`, which differ only in the HTTP method.
 */
async function requestWithJsonBody<T>(
  method: string,
  path: string,
  payload: unknown,
  clerkToken?: string | null,
): Promise<T> {
  const result = await sendRequest(method, path, {
    clerkToken,
    jsonPayload: payload,
    withBody: true,
  });

  if (!result.ok) {
    const text = await result.text().catch(() => "");
    throw new Error(text || `Failed to ${method} ${path}`);
  }

  const contentType = result.headers.get("content-type");
  if (contentType?.includes("application/json")) {
    return (await result.json()) as T;
  }
  return undefined as T;
}

export async function get<T>(
  path: string,
  clerkToken?: string | null,
  signal?: AbortSignal,
  extraHeaders?: Record<string, string>,
) {
  const result = await sendRequest("GET", path, { clerkToken, signal, extraHeaders });

  if (result.ok) {
    const json = await result.json();
    return json as T;
  }
  throw new HttpError(`Failed to GET ${path}`, result.status);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export async function post(path: string, payload: any, clerkToken?: string | null) {
  return sendRequest("POST", path, { clerkToken, jsonPayload: payload, withBody: true });
}

/**
 * POSTs a JSON body and returns the parsed JSON response as `T`, throwing on a
 * non-ok response (using the response text when present). Mirrors `patchJson`:
 * a body is only parsed when the response is JSON, so endpoints that answer a
 * successful POST with an empty body (`Promise<void>` callers) are handled too.
 * Use this instead of the low-level `post` whenever the caller just needs the
 * parsed body; reach for `post` only when the raw `Response` is genuinely needed.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export async function postJson<T>(
  path: string,
  payload: any,
  clerkToken?: string | null,
): Promise<T> {
  return requestWithJsonBody<T>("POST", path, payload, clerkToken);
}

/**
 * PATCHes a JSON body and returns the parsed JSON response as `T`, throwing on a
 * non-ok response (using the response text when present). Mirrors `postJson`: a
 * body is only parsed when the response is JSON, so endpoints that answer a
 * successful PATCH with an empty body (`Promise<void>` callers) are handled too.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export async function patchJson<T>(
  path: string,
  payload: any,
  clerkToken?: string | null,
): Promise<T> {
  return requestWithJsonBody<T>("PATCH", path, payload, clerkToken);
}

export async function del(path: string, clerkToken?: string | null) {
  const result = await sendRequest("DELETE", path, { clerkToken });

  if (!result.ok) {
    throw new Error(`Failed to DELETE ${path}`);
  }
}
import { del, get, postJson } from "../http";
import type { V3EventResults, V3Tournament } from "./view/results";

/** Header the anonymous share-view API expects. Never put the token in a URI. */
export const SHARE_TOKEN_HEADER = "x-flunge-share-token";

export interface ShareLinkEnvelope {
  id: string;
  token: string;
  url: string;
  createdAt: string;
  expiresAt: string;
  revokedAt?: string;
}

export interface ShareLink extends ShareLinkEnvelope {
  fencerId: string;
}

export interface PlanShareLink extends ShareLinkEnvelope {
  fencerIds: string[];
  includePriority: boolean;
  includeNotes: boolean;
}

export interface ShareResultsView {
  fencerId: string;
  fencerName: string;
  createdAt: string;
  expiresAt: string;
  tournaments: V3Tournament[];
}

function shareTokenHeaders(token: string): Record<string, string> {
  return { [SHARE_TOKEN_HEADER]: token };
}

export async function mintShareLink(
  fencerId: string,
  expiresInDays: number,
  clerkToken?: string | null,
) {
  return postJson<ShareLink>("/api/v3/share/results", { fencerId, expiresInDays }, clerkToken);
}

export async function listShareLinks(fencerId: string, clerkToken?: string | null) {
  return get<ShareLink[]>(
    `/api/v3/share/results?fencerId=${encodeURIComponent(fencerId)}`,
    clerkToken,
  );
}

export async function revokeShareLink(id: string, clerkToken?: string | null) {
  await del(`/api/v3/share/results/${encodeURIComponent(id)}`, clerkToken);
}

export async function mintPlanShareLink(
  fencerIds: string[],
  expiresInDays: number,
  includePriority: boolean,
  includeNotes: boolean,
  clerkToken?: string | null,
) {
  return postJson<PlanShareLink>(
    "/api/v3/share/plan",
    { fencerIds, expiresInDays, includePriority, includeNotes },
    clerkToken,
  );
}

export async function listPlanShareLinks(clerkToken?: string | null) {
  return get<PlanShareLink[]>("/api/v3/share/plan", clerkToken);
}

export async function revokePlanShareLink(id: string, clerkToken?: string | null) {
  await del(`/api/v3/share/plan/${encodeURIComponent(id)}`, clerkToken);
}

/**
 * Anonymous read of the share-view payload. Sends the bearer token in
 * `X-Flunge-Share-Token` and never an Authorization header — visibility is
 * the link owner's, resolved server-side, even if the recipient is signed in.
 */
export async function getShareResultsView(token: string) {
  return get<ShareResultsView>(
    "/api/v3/share/results/view",
    null,
    undefined,
    shareTokenHeaders(token),
  );
}

export async function getShareResultsEvent(token: string, tournamentId: string, eventId: string) {
  return get<V3EventResults>(
    `/api/v3/share/results/view/events/${encodeURIComponent(tournamentId)}/${encodeURIComponent(eventId)}`,
    null,
    undefined,
    shareTokenHeaders(token),
  );
}
import type { ElementType, ReactNode } from "react";
import { Box, Button, CircularProgress, Sheet, Stack, Typography } from "@mui/joy";
import { Warning } from "@mui/icons-material";

export interface LoadingStateProps {
  message?: string;
  size?: "sm" | "md" | "lg";
}

export function LoadingState({ message, size }: LoadingStateProps) {
  if (message) {
    return (
      <Stack direction="row" spacing={1} alignItems="center" justifyContent="center" sx={{ py: 2 }}>
        <CircularProgress size={size ?? "sm"} />
        <Typography level="body-sm">{message}</Typography>
      </Stack>
    );
  }
  return (
    <Box
      sx={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        py: 8,
      }}
    >
      <CircularProgress size={size ?? "lg"} />
    </Box>
  );
}

export interface StateCardProps {
  icon: ElementType;
  iconColor?: string;
  title: string;
  message: string;
  action?: ReactNode;
}

export function StateCard({
  icon: Icon,
  iconColor = "text.tertiary",
  title,
  message,
  action,
}: StateCardProps) {
  return (
    <Sheet
      variant="outlined"
      sx={{
        p: 4,
        borderRadius: "lg",
        textAlign: "center",
      }}
    >
      <Icon sx={{ fontSize: 40, color: iconColor, mb: 1 }} />
      <Typography level="title-md" sx={{ mb: 0.5 }}>
        {title}
      </Typography>
      <Typography level="body-sm" sx={{ color: "text.secondary", mb: action ? 2 : 0 }}>
        {message}
      </Typography>
      {action}
    </Sheet>
  );
}

export interface ErrorStateCardProps {
  title?: string;
  message: string;
  retryLabel?: string;
  onRetry?: () => void;
}

export function ErrorStateCard({
  title = "Something went wrong",
  message,
  retryLabel = "Retry",
  onRetry,
}: ErrorStateCardProps) {
  return (
    <StateCard
      icon={Warning}
      iconColor="warning.main"
      title={title}
      message={message}
      action={
        onRetry ? (
          <Button variant="soft" onClick={onRetry}>
            {retryLabel}
          </Button>
        ) : undefined
      }
    />
  );
}

