import { HttpError } from "./api/http";

export type ShareLoadFailureKind = "permanent" | "transient";

export const SHARE_LOAD_FAILURE_COPY: Record<
  ShareLoadFailureKind,
  { title: string; message: string }
> = {
  permanent: {
    title: "This link isn't available.",
    message: "Check the link with whoever shared it.",
  },
  transient: {
    title: "Couldn't load this right now.",
    message: "Try again in a moment.",
  },
};

/** 4xx that mean the request did not complete, not that the link itself is bad. */
const TRANSIENT_CLIENT_STATUSES = new Set([408, 429]);

/**
 * Classify a failed share-view fetch so the recipient page can tell "this
 * link is the problem" from "the service could not answer".
 *
 * Permanent: the backend answered that the token is missing, unknown,
 * revoked, expired, or malformed (404 / 410 / other 4xx except 408/429).
 * Transient: 5xx, 408, 429, a network failure, or any error without a
 * status — including the mid-deploy connection-refused window. Ambiguous
 * failures are transient: better to ask a valid-link holder to retry than
 * to tell them the link is broken.
 */
export function classifyShareLoadFailure(error: unknown): ShareLoadFailureKind {
  if (error instanceof HttpError) {
    if (TRANSIENT_CLIENT_STATUSES.has(error.status)) {
      return "transient";
    }
    if (error.status >= 400 && error.status < 500) {
      return "permanent";
    }
    return "transient";
  }
  return "transient";
}
import { HttpError } from "./api/http";
import { classifyShareLoadFailure } from "./shareLoadFailure";

describe("classifyShareLoadFailure", () => {
  it.each([
    [400, "permanent"],
    [404, "permanent"],
    [410, "permanent"],
    [403, "permanent"],
    [408, "transient"],
    [429, "transient"],
    [500, "transient"],
    [502, "transient"],
    [503, "transient"],
    [504, "transient"],
  ] as const)("classifies HTTP %s as %s", (status, kind) => {
    expect(classifyShareLoadFailure(new HttpError("Failed to GET", status))).toBe(kind);
  });

  it("classifies a network/unknown error as transient", () => {
    expect(classifyShareLoadFailure(new TypeError("Failed to fetch"))).toBe("transient");
    expect(classifyShareLoadFailure(new Error("Failed to GET"))).toBe("transient");
    expect(classifyShareLoadFailure("nope")).toBe("transient");
    expect(classifyShareLoadFailure(undefined)).toBe("transient");
  });
});
import { LinkOff } from "@mui/icons-material";
import { Button, Stack } from "@mui/joy";

import { SHARE_LOAD_FAILURE_COPY, type ShareLoadFailureKind } from "../shareLoadFailure";
import { StateCard } from "./PageStates";

/**
 * Recipient-facing card for a failed share-view load. Used by the results
 * share page today; the plan share page should use the same component so
 * the two copies cannot drift.
 */
export function ShareLoadFailureState({
  kind,
  onRetry,
}: {
  kind: ShareLoadFailureKind;
  onRetry?: () => void;
}) {
  const copy = SHARE_LOAD_FAILURE_COPY[kind];
  return (
    <Stack alignItems="center" justifyContent="center" sx={{ minHeight: "50vh", p: 2 }}>
      <StateCard
        icon={LinkOff}
        title={copy.title}
        message={copy.message}
        action={
          onRetry ? (
            <Button variant="soft" onClick={onRetry}>
              Try again
            </Button>
          ) : undefined
        }
      />
    </Stack>
  );
}
import { fireEvent, render, screen } from "@testing-library/react";

import { ShareLoadFailureState } from "./ShareLoadFailureState";

describe("ShareLoadFailureState", () => {
  it("renders permanent copy without a retry action", () => {
    render(<ShareLoadFailureState kind="permanent" />);

    expect(screen.getByText("This link isn't available.")).toBeTruthy();
    expect(screen.getByText("Check the link with whoever shared it.")).toBeTruthy();
    expect(screen.queryByRole("button", { name: "Try again" })).toBeNull();
  });

  it("renders transient copy and calls onRetry from Try again", () => {
    const onRetry = jest.fn();
    render(<ShareLoadFailureState kind="transient" onRetry={onRetry} />);

    expect(screen.getByText("Couldn't load this right now.")).toBeTruthy();
    expect(screen.getByText("Try again in a moment.")).toBeTruthy();
    fireEvent.click(screen.getByRole("button", { name: "Try again" }));
    expect(onRetry).toHaveBeenCalledTimes(1);
  });
});
